package pe.vichaval.gestionriego.caja.service;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.vichaval.gestionriego.caja.dto.*;import pe.vichaval.gestionriego.caja.entity.*;import pe.vichaval.gestionriego.caja.repository.*;import pe.vichaval.gestionriego.tesoreria.repository.PagoRepository;import pe.vichaval.gestionriego.usuario.repository.UsuarioRepository;
@Service@Transactional public class CajaService{private final EgresoRepository egresos;private final DevolucionRepository devoluciones;private final CierreCajaRepository cierres;private final PagoRepository pagos;private final UsuarioRepository usuarios;public CajaService(EgresoRepository e,DevolucionRepository d,CierreCajaRepository c,PagoRepository p,UsuarioRepository u){egresos=e;devoluciones=d;cierres=c;pagos=p;usuarios=u;}public List<Egreso>egresos(){return egresos.findAllByOrderByFechaDescIdDesc();}public List<Devolucion>devoluciones(){return devoluciones.findAllByOrderByFechaDescIdDesc();}public List<CierreCaja>cierres(){return cierres.findAllByOrderByFechaDesc();}public void crearEgreso(EgresoForm f,Long uid){if(egresos.existsByComprobanteIgnoreCase(f.getComprobante()))throw new IllegalArgumentException("Comprobante duplicado");var u=usuarios.findById(uid).orElseThrow();egresos.save(new Egreso("EG-%06d".formatted(egresos.count()+1),f,u));}public void anularEgreso(Long id,String m){egresos.findById(id).orElseThrow().anular(m);}public void solicitar(DevolucionForm f,Long uid){var p=pagos.findById(f.getPagoId()).orElseThrow(()->new IllegalArgumentException("Pago no encontrado"));if(!"CONFIRMADO".equals(p.getEstado()))throw new IllegalStateException("Solo pagos confirmados");BigDecimal disponible=p.getMonto().subtract(devoluciones.totalPorPago(p.getId()));if(f.getMonto().compareTo(disponible)>0)throw new IllegalStateException("La devolución supera el monto disponible");devoluciones.save(new Devolucion("DV-%06d".formatted(devoluciones.count()+1),p,f.getMonto(),f.getMotivo(),usuarios.findById(uid).orElseThrow()));}public void aprobar(Long id){devoluciones.findById(id).orElseThrow().aprobar();}public void ejecutar(Long id){devoluciones.findById(id).orElseThrow().ejecutar();}public void rechazar(Long id){devoluciones.findById(id).orElseThrow().rechazar();}public void cerrar(CierreCajaForm f,Long uid){if(cierres.existsByFecha(f.getFecha()))throw new IllegalStateException("Ya existe cierre para la fecha");BigDecimal ingresos=pagos.findAll().stream().filter(p->f.getFecha().equals(p.getFecha())&&"CONFIRMADO".equals(p.getEstado())).map(p->p.getMonto()).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal e=egresos.totalFecha(f.getFecha());BigDecimal d=devoluciones.totalFecha(f.getFecha());cierres.save(new CierreCaja(f.getFecha(),f.getSaldoInicial(),ingresos,e,d,f.getSaldoContado(),f.getObservaciones(),usuarios.findById(uid).orElseThrow()));}}
